    public readonly partial record struct B2World : IDisposable
    {
        /// Destroy a world
        public void Dispose()
        {
            Box2D.Dispose(this);
        }

        /// World id validation. Provides validation for up to 64K allocations.
        public Bool8 IsValid()
        {
            return Box2D.WorldIsValid(this);
        }

        /// Simulate a world for one time step. This performs collision detection, integration, and constraint solution.
        /// <param name="timeStep">The amount of time to simulate, this should be a fixed number. Usually 1/60. </param>
        /// <param name="subStepCount">The number of sub-steps, increasing the sub-step count can increase accuracy. Usually 4. </param>
        public void Step(float timeStep, int subStepCount)
        {
            Box2D.WorldStep(this, timeStep, subStepCount);
        }

        /// Call this to draw shapes and other debug draw data
        public void Draw(in B2DebugDraw draw)
        {
            Box2D.WorldDraw(this, draw);
        }

        /// Get the body events for the current time step. The event data is transient. Do not store a reference to this data.
        public B2BodyEvents GetBodyEvents()
        {
            return Box2D.WorldGetBodyEvents(this);
        }

        /// Get sensor events for the current time step. The event data is transient. Do not store a reference to this data.
        public B2SensorEvents GetSensorEvents()
        {
            return Box2D.WorldGetSensorEvents(this);
        }

        /// Get contact events for this current time step. The event data is transient. Do not store a reference to this data.
        public B2ContactEvents GetContactEvents()
        {
            return Box2D.WorldGetContactEvents(this);
        }

        /// Overlap test for all shapes that *potentially* overlap the provided AABB
        public B2TreeStats OverlapAabb(B2Aabb aabb, B2QueryFilter filter, B2OverlapResultFcn fcn, nint context)
        {
            return Box2D.WorldOverlapAabb(this, aabb, filter, fcn, context);
        }

        /// Overlap test for all shapes that overlap the provided shape proxy.
        public B2TreeStats OverlapShape(
            in B2ShapeProxy proxy,
            B2QueryFilter filter,
            B2OverlapResultFcn fcn,
            nint context
        )
        {
            return Box2D.WorldOverlapShape(this, proxy, filter, fcn, context);
        }

        /// Cast a ray into the world to collect shapes in the path of the ray.
        /// Your callback function controls whether you get the closest point, any point, or n-points.
        /// NOTE: The callback function may receive shapes in any order
        /// <param name="origin">The start point of the ray </param>
        /// <param name="translation">The translation of the ray from the start point to the end point </param>
        /// <param name="filter">Contains bit flags to filter unwanted shapes from the results </param>
        /// <param name="fcn">A user implemented callback function </param>
        /// <param name="context">A user context that is passed along to the callback function </param>
        /// RETURN: traversal performance counters
        public B2TreeStats CastRay(
            float2 origin,
            float2 translation,
            B2QueryFilter filter,
            B2CastResultFcn fcn,
            nint context
        )
        {
            return Box2D.WorldCastRay(this, origin, translation, filter, fcn, context);
        }

        /// Cast a ray into the world to collect the closest hit. This is a convenience function. Ignores initial overlap.
        /// This is less general than b2World_CastRay() and does not allow for custom filtering.
        public B2RayResult CastRayClosest(float2 origin, float2 translation, B2QueryFilter filter)
        {
            return Box2D.WorldCastRayClosest(this, origin, translation, filter);
        }

        /// Cast a shape through the world. Similar to a cast ray except that a shape is cast instead of a point.
        /// SEE: b2World_CastRay
        public B2TreeStats CastShape(
            in B2ShapeProxy proxy,
            float2 translation,
            B2QueryFilter filter,
            B2CastResultFcn fcn,
            nint context
        )
        {
            return Box2D.WorldCastShape(this, proxy, translation, filter, fcn, context);
        }

        /// Cast a capsule mover through the world. This is a special shape cast that handles sliding along other shapes while reducing
        /// clipping.
        public float CastMover(in B2Capsule mover, float2 translation, B2QueryFilter filter)
        {
            return Box2D.WorldCastMover(this, mover, translation, filter);
        }

        /// Collide a capsule mover with the world, gathering collision planes that can be fed to b2SolvePlanes. Useful for
        /// kinematic character movement.
        public void CollideMover(in B2Capsule mover, B2QueryFilter filter, B2PlaneResultFcn fcn, nint context)
        {
            Box2D.WorldCollideMover(this, mover, filter, fcn, context);
        }

        /// Enable/disable sleep. If your application does not need sleeping, you can gain some performance
        /// by disabling sleep completely at the world level.
        /// SEE: b2WorldDef
        public void EnableSleeping(Bool8 flag)
        {
            Box2D.WorldEnableSleeping(this, flag);
        }

        /// Is body sleeping enabled?
        public Bool8 IsSleepingEnabled()
        {
            return Box2D.WorldIsSleepingEnabled(this);
        }

        /// Enable/disable continuous collision between dynamic and static bodies. Generally you should keep continuous
        /// collision enabled to prevent fast moving objects from going through static objects. The performance gain from
        /// disabling continuous collision is minor.
        /// SEE: b2WorldDef
        public void EnableContinuous(Bool8 flag)
        {
            Box2D.WorldEnableContinuous(this, flag);
        }

        /// Is continuous collision enabled?
        public Bool8 IsContinuousEnabled()
        {
            return Box2D.WorldIsContinuousEnabled(this);
        }

        /// Adjust the restitution threshold. It is recommended not to make this value very small
        /// because it will prevent bodies from sleeping. Usually in meters per second.
        /// SEE: b2WorldDef
        public void SetRestitutionThreshold(float value)
        {
            Box2D.WorldSetRestitutionThreshold(this, value);
        }

        /// Get the the restitution speed threshold. Usually in meters per second.
        public float GetRestitutionThreshold()
        {
            return Box2D.WorldGetRestitutionThreshold(this);
        }

        /// Adjust the hit event threshold. This controls the collision speed needed to generate a b2ContactHitEvent.
        /// Usually in meters per second.
        /// SEE: b2WorldDef::hitEventThreshold
        public void SetHitEventThreshold(float value)
        {
            Box2D.WorldSetHitEventThreshold(this, value);
        }

        /// Get the the hit event speed threshold. Usually in meters per second.
        public float GetHitEventThreshold()
        {
            return Box2D.WorldGetHitEventThreshold(this);
        }

        /// Register the custom filter callback. This is optional.
        public void SetCustomFilterCallback(B2CustomFilterFcn fcn, nint context)
        {
            Box2D.WorldSetCustomFilterCallback(this, fcn, context);
        }

        /// Register the pre-solve callback. This is optional.
        public void SetPreSolveCallback(B2PreSolveFcn fcn, nint context)
        {
            Box2D.WorldSetPreSolveCallback(this, fcn, context);
        }

        /// Set the gravity vector for the entire world. Box2D has no concept of an up direction and this
        /// is left as a decision for the application. Usually in m/s^2.
        /// SEE: b2WorldDef
        public void SetGravity(float2 gravity)
        {
            Box2D.WorldSetGravity(this, gravity);
        }

        /// Get the gravity vector
        public float2 GetGravity()
        {
            return Box2D.WorldGetGravity(this);
        }

        /// Apply a radial explosion
        /// <param name="explosionDef">The explosion definition </param>
        public void Explode(in B2ExplosionDef explosionDef)
        {
            Box2D.WorldExplode(this, explosionDef);
        }

        /// Adjust contact tuning parameters
        /// <param name="hertz">The contact stiffness (cycles per second) </param>
        /// <param name="dampingRatio">The contact bounciness with 1 being critical damping (non-dimensional) </param>
        /// <param name="pushSpeed">The maximum contact constraint push out speed (meters per second) </param>
        /// NOTE: Advanced feature
        public void SetContactTuning(float hertz, float dampingRatio, float pushSpeed)
        {
            Box2D.WorldSetContactTuning(this, hertz, dampingRatio, pushSpeed);
        }

        /// Set the maximum linear speed. Usually in m/s.
        public void SetMaximumLinearSpeed(float maximumLinearSpeed)
        {
            Box2D.WorldSetMaximumLinearSpeed(this, maximumLinearSpeed);
        }

        /// Get the maximum linear speed. Usually in m/s.
        public float GetMaximumLinearSpeed()
        {
            return Box2D.WorldGetMaximumLinearSpeed(this);
        }

        /// Enable/disable constraint warm starting. Advanced feature for testing. Disabling
        /// warm starting greatly reduces stability and provides no performance gain.
        public void EnableWarmStarting(Bool8 flag)
        {
            Box2D.WorldEnableWarmStarting(this, flag);
        }

        /// Is constraint warm starting enabled?
        public Bool8 IsWarmStartingEnabled()
        {
            return Box2D.WorldIsWarmStartingEnabled(this);
        }

        /// Get the number of awake bodies.
        public int GetAwakeBodyCount()
        {
            return Box2D.WorldGetAwakeBodyCount(this);
        }

        /// Get the current world performance profile
        public B2Profile GetProfile()
        {
            return Box2D.WorldGetProfile(this);
        }

        /// Get world counters and sizes
        public B2Counters GetCounters()
        {
            return Box2D.WorldGetCounters(this);
        }

        /// Set the user data pointer.
        public void SetUserData(nint userData)
        {
            Box2D.WorldSetUserData(this, userData);
        }

        /// Get the user data pointer.
        public unsafe void* GetUserData()
        {
            return Box2D.WorldGetUserData(this);
        }

        /// Set the friction callback. Passing NULL resets to default.
        public void SetFrictionCallback(B2FrictionCallback callback)
        {
            Box2D.WorldSetFrictionCallback(this, callback);
        }

        /// Set the restitution callback. Passing NULL resets to default.
        public void SetRestitutionCallback(B2RestitutionCallback callback)
        {
            Box2D.WorldSetRestitutionCallback(this, callback);
        }

        /// Dump memory stats to box2d_memory.txt
        public void DumpMemoryStats()
        {
            Box2D.WorldDumpMemoryStats(this);
        }

        /// This is for internal testing
        public void RebuildStaticTree()
        {
            Box2D.WorldRebuildStaticTree(this);
        }

        /// This is for internal testing
        public void EnableSpeculative(Bool8 flag)
        {
            Box2D.WorldEnableSpeculative(this, flag);
        }

        /// Create a rigid body given a definition. No reference to the definition is retained. So you can create the definition
        /// on the stack and pass it as a pointer.
        /// WARNING: This function is locked during callbacks.
        public B2Body CreateBody(in B2BodyDef def)
        {
            return Box2D.CreateBody(this, def);
        }

        /// Create a distance joint
        /// SEE: b2DistanceJointDef for details
        public B2DistanceJoint CreateDistanceJoint(in B2DistanceJointDef def)
        {
            return Box2D.CreateDistanceJoint(this, def);
        }

        /// Create a motor joint
        /// SEE: b2MotorJointDef for details
        public B2MotorJoint CreateMotorJoint(in B2MotorJointDef def)
        {
            return Box2D.CreateMotorJoint(this, def);
        }

        /// Create a mouse joint
        /// SEE: b2MouseJointDef for details
        public B2MouseJoint CreateMouseJoint(in B2MouseJointDef def)
        {
            return Box2D.CreateMouseJoint(this, def);
        }

        /// Create a filter joint.
        /// SEE: b2FilterJointDef for details
        public B2FilterJoint CreateFilterJoint(in B2FilterJointDef def)
        {
            return Box2D.CreateFilterJoint(this, def);
        }

        /// Create a prismatic (slider) joint.
        /// SEE: b2PrismaticJointDef for details
        public B2PrismaticJoint CreatePrismaticJoint(in B2PrismaticJointDef def)
        {
            return Box2D.CreatePrismaticJoint(this, def);
        }

        /// Create a revolute joint
        /// SEE: b2RevoluteJointDef for details
        public B2RevoluteJoint CreateRevoluteJoint(in B2RevoluteJointDef def)
        {
            return Box2D.CreateRevoluteJoint(this, def);
        }

        /// Create a weld joint
        /// SEE: b2WeldJointDef for details
        public B2WeldJoint CreateWeldJoint(in B2WeldJointDef def)
        {
            return Box2D.CreateWeldJoint(this, def);
        }

        /// Create a wheel joint
        /// SEE: b2WheelJointDef for details
        public B2WheelJoint CreateWheelJoint(in B2WheelJointDef def)
        {
            return Box2D.CreateWheelJoint(this, def);
        }

        ///
        [FieldOffset(0)]
        public readonly ushort Index1;

        ///
        [FieldOffset(2)]
        public readonly ushort Generation;
    }

    /// Body id references a body instance. This should be treated as an opaque handle.
    [StructLayout(LayoutKind.Explicit, Size = 8)]
    public readonly partial record struct B2Body : IDisposable
    {
        /// Destroy a rigid body given an id. This destroys all shapes and joints attached to the body.
        /// Do not keep references to the associated shapes and joints.
