        {
            Box2D.Dispose(this);
        }

        /// Body identifier validation. Can be used to detect orphaned ids. Provides validation for up to 64K allocations.
        public Bool8 IsValid()
        {
            return Box2D.BodyIsValid(this);
        }

        /// Get the body type: static, kinematic, or dynamic
        public B2BodyType GetBodyType()
        {
            return Box2D.GetBodyType(this);
        }

        /// Change the body type. This is an expensive operation. This automatically updates the mass
        /// properties regardless of the automatic mass setting.
        public void SetType(B2BodyType type)
        {
            Box2D.BodySetType(this, type);
        }

        /// Set the body name. Up to 31 characters excluding 0 termination.
        public unsafe void SetName(byte* name)
        {
            Box2D.BodySetName(this, name);
        }

        /// Get the body name. May be null.
        public unsafe byte* GetName()
        {
            return Box2D.BodyGetName(this);
        }

        /// Set the user data for a body
        public void SetUserData(nint userData)
        {
            Box2D.BodySetUserData(this, userData);
        }

        /// Get the user data stored in a body
        public unsafe void* GetUserData()
        {
            return Box2D.BodyGetUserData(this);
        }

        /// Get the world position of a body. This is the location of the body origin.
