        {
            return Box2D.BodyGetLocalVector(this, worldVector);
        }

        /// Get a world vector on a body given a local vector
        public float2 GetWorldVector(float2 localVector)
        {
            return Box2D.BodyGetWorldVector(this, localVector);
        }

        /// Get the linear velocity of a body&apos;s center of mass. Usually in meters per second.
        public float2 GetLinearVelocity()
